function date(v){if(v instanceof Date)return new Date(v.getTime());const s=String(v||'').trim();let m=s.match(/^(\d{4})-(\d{2})-(\d{2})$/),y,mo,d;if(m){[,y,mo,d]=m}else{m=s.match(/^(\d{1,2})[./-](\d{1,2})[./-]?(\d{4})$/);if(!m)return null;[,d,mo,y]=m}const x=new Date(Date.UTC(+y,+mo-1,+d,12));return x.getUTCFullYear()===+y&&x.getUTCMonth()===+mo-1&&x.getUTCDate()===+d?x:null;}
