function search(result,query){const stop=new Set(['QUE','CUANDO','CUANTO','CUANTOS','CUAL','ES','EL','LA','LOS','LAS','DE','DEL','EN','PARA','SE','UN','UNA','DIAS','PLAZO','PLAZOS','FECHA','FECHAS','HAY','TENGO']);const clean=v=>norm(v).replace(/SUBSANAR|SUBSANACION/g,'SUBSAN').replace(/PRESENTAN|PRESENTAR|PRESENTACION/g,'PRESENT').replace(/DOCUMENTOS/g,'REQUISITOS').replace(/FIRMAR|FIRMA|SUSCRIBIR/g,'SUSCRIPCION').replace(/CONTRATO|CONTRATACION/g,'CONTRAT').replace(/COTIZACION|INDAGACION/g,'INTERACCION');const words=clean(query).split(/[^A-Z0-9]+/).filter(w=>w.length>2&&!stop.has(w));if(!words.length)return [];const ranked=result.rows.map(r=>({r,score:words.reduce((n,w)=>n+(clean(r.label).includes(w)?3:clean(r.phase).includes(w)?1:clean(r.basis).includes(w)?0.5:0),0)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score);const best=ranked[0]?.score||0;return ranked.filter(x=>x.score===best).slice(0,3).map(x=>x.r);}

